import{_ as n,C as i,o as r,c as s,j as t,a,E as d,a2 as l}from"./chunks/framework.Di-jvWLj.js";const x=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/index.md","filePath":"deployment/index.md","lastUpdated":1793088333000}'),c={name:"deployment/index.md"},p={id:"deployment",tabindex:"-1"};function h(m,e,u,g,b,f){const o=i("Badge");return r(),s("div",null,[t("h1",p,[e[0]||(e[0]=a("Deployment ",-1)),d(o,{type:"warning",text:"Planned"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#deployment","aria-label":'Permalink to "Deployment <Badge type="warning" text="Planned" />"'},"​",-1))]),e[3]||(e[3]=l(`<div class="warning custom-block"><p class="custom-block-title">Planned</p><p>The app and the CLI exist: <a href="/guide/app"><code>@chamvi/app</code></a> boots an agent repository from env and <a href="/reference/cli"><code>@chamvi/cli</code></a> runs it with <code>chamvi start</code>, draining on <code>SIGTERM</code>. The <a href="/deployment/docker">base image</a> <code>ghcr.io/chamvi/node</code> exists too. The Helm chart and the template repository do not exist yet; these pages describe the planned setup so you can see where chamvi is going.</p></div><p>The target workflow: agents live in their own GitHub repository, CI builds a Docker image, and Flux deploys it to your Kubernetes cluster. Every agent repository is an app with one or more agents, its own store connection, its own GitHub App and its own channels.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span>agent repo --push--&gt; CI --image--&gt; registry --Flux image automation--&gt; HelmRelease --&gt; cluster</span></span>
<span class="line"><span>                                                                            |</span></span>
<span class="line"><span>                                         OpenClaw --MCP--&gt; app (/mcp) --hooks--&gt; OpenClaw</span></span>
<span class="line"><span>                                         GitHub ---webhooks---&gt; app (/channels/github) --comments--&gt; GitHub</span></span></code></pre></div><h2 id="pieces" tabindex="-1">Pieces <a class="header-anchor" href="#pieces" aria-label="Permalink to &quot;Pieces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Built as</th></tr></thead><tbody><tr><td><a href="/reference/app"><code>@chamvi/app</code></a> + <a href="/reference/cli"><code>@chamvi/cli</code></a> (exist)</td><td><code>createApp({ agents, modules })</code> boots config, store, engine (with its channels) and HTTP in order and tears them down in reverse, draining on <code>SIGTERM</code>. The <code>chamvi</code> bin with <code>dev</code>, <code>build</code>, <code>start</code>, <code>run-job</code> and <code>migrate</code>. See <a href="/guide/app">Apps &amp; Modules</a></td></tr><tr><td><a href="/deployment/docker">Base image</a> (exists)</td><td><code>ghcr.io/chamvi/node</code>: Node 24 on Debian trixie slim, tini, uid 1000, <code>linux/amd64</code> and <code>linux/arm64</code>; agent repositories use a two-stage Dockerfile</td></tr><tr><td><a href="/deployment/kubernetes">Helm chart</a></td><td>One shared OCI chart for every agent app; each repository gets a small <code>HelmRelease</code></td></tr><tr><td>Template repository</td><td>A GitHub template with an example agent, Dockerfile, CI that builds and tags images for Flux, and example Flux manifests</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Configuration comes from <a href="/reference/app#environment">environment variables</a>, typically from Kubernetes Secrets: the database URL, the HTTP port, the default model and provider API keys (<code>CHAMVI_MODEL</code>, <code>CHAMVI_PROVIDER_&lt;NAME&gt;_*</code> or the bare <code>ANTHROPIC_API_KEY</code>, ...; only providers you declare, no gateway by default, see <a href="/guide/models">Pick a Model</a>; <code>chamvi start --check</code> checks them, the store and the agent folders in CI with the production or staging env), static API tokens for machine clients, and OpenClaw and GitHub settings. How the Secrets get into the cluster (plain Secrets, SOPS, External Secrets) is the cluster&#39;s choice.</p><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><p>Planned: OpenTelemetry spans for runs and steps next to the AI SDK&#39;s own telemetry, Prometheus metrics from the HTTP app, and structured JSON logs.</p><h2 id="read-next" tabindex="-1">Read next <a class="header-anchor" href="#read-next" aria-label="Permalink to &quot;Read next&quot;">​</a></h2><ul><li><a href="/deployment/docker">Docker Image</a></li><li><a href="/deployment/kubernetes">Kubernetes &amp; Flux</a></li><li><a href="/deployment/replicas">Multiple Replicas</a></li><li><a href="/deployment/openclaw">OpenClaw</a></li><li><a href="/deployment/github-app">GitHub App</a></li></ul>`,11))])}const v=n(c,[["render",h]]);export{x as __pageData,v as default};
